@strawberry.type
class Query:
    @strawberry.field
    async def ticket_transcript(self, info: Info, ticket_id: str) -> Optional[TranscriptType]:
        user = info.context.get("current_user")
        if not user:
            raise HTTPException(status_code=401, detail="Authentication required")

        loader: DataLoader = info.context["transcript_loader"]
        transcript = await loader.load(ticket_id)
        if not transcript:
            return None

        if transcript.customer_user_id != user.id and not user.is_support_rep:
            raise HTTPException(status_code=403, detail="Forbidden: access to support ticket transcript denied")

        return TranscriptType(
            ticket_id=transcript.ticket_id,
            messages=transcript.raw_chat_history,
            assigned_agent_id=transcript.agent_id
        )
